import * as menu from "@zag-js/menu";
import { positionerStyle } from "marko-zag";
import { cn } from "../../../lib/utils.ts";
import Icon from "../icon/icon.marko";
import Submenu from "./submenu.marko";

export interface DropdownMenuItem {
  type?: "item" | "separator" | "label" | "checkbox" | "radio" | "sub";
  value?: string;
  label?: string;
  disabled?: boolean;
  shortcut?: string;
  /** Upstream `variant: "default" | "destructive"`, emitted as `data-variant`. */
  variant?: "default" | "destructive";
  /** Emits `data-inset` — indents the entry to align with icon-bearing siblings. */
  inset?: boolean;
  /** Checked state for `type="checkbox"` and `type="radio"` entries. */
  checked?: boolean;
  /** Groups radio items — required for `type: "radio"` entries. */
  radioGroup?: string;
  /** `type: "radio"` entries only — this entry's value within its `radioGroup`. */
  radioValue?: string;
  /**
   * `type: "sub"` entries only — the nested submenu's own item list. One
   * level deep: a `type: "sub"` entry inside a submenu's own `subEntries` is
   * not wired (same limit as menubar's submenu).
   */
  subEntries?: DropdownMenuItem[];
}

// Attr-tag form of DropdownMenuItem. A SINGLE attr tag name (`item`) carries
// all five kinds (discriminated by `type`) rather than separate per-kind
// attr tags: Marko collects each attr-tag NAME into its own independent
// iterable on `input` with no shared ordering between differently-named
// siblings, so `<@item>`/`<@separator>`/`<@label>` as distinct tag names
// could not preserve call-site interleaving. One name with a `type`
// discriminant keeps document order intact by construction (same design as
// context-menu.marko). `content` lets an item or label carry a markup body;
// the plain `label` string renders as the fallback when no body is supplied.
export interface DropdownMenuItemAttrs extends DropdownMenuItem {
  content?: Marko.Body;
}

export interface Input {
  trigger: Marko.Body<[Record<string, unknown>]>;
  items?: DropdownMenuItem[];
  item?: Marko.AttrTag<DropdownMenuItemAttrs>;
  select?: (value: string) => void;
  class?: string;
}

<machine-props/machineProps from=input pick=menu.props
  onSelect(details: menu.SelectionDetails) {
    input.select?.(details.value);
  }/>
<service/service machine=() => menu.machine props=machineProps/>
<connect/api=(service, normalizeProps) =>
  menu.connect(service, normalizeProps)
  service=service
/>

<const/{ class: className, trigger }=input/>
// Normalize whichever source was supplied into ONE entries list so the
// render path below never branches. Attr tags win when present (compound is
// primary per the compound-tag-dx report); `items=` is the fallback.
// `items=` entries never carry a body, so each is mapped into the
// DropdownMenuItemAttrs shape with an explicit undefined `content` — no
// casts needed (mirrors accordion/toggle-group).
<const/attrItems=[...(input.item ?? [])]/>
<const/entries=(attrItems.length > 0 ? attrItems : (input.items ?? []).map((item) => ({ ...item, content: undefined as Marko.Body | undefined })))/>

// Getter handed to each <Submenu> child so it can call `setParent` on this
// menu's raw service (see submenu.marko for the full wiring rationale).
<const/getOwnService=() => service.service/>

<${trigger}({ ...api().getTriggerProps(), "data-slot": "dropdown-menu-trigger" })/>
<portal>
  <if=api().open>
    <div ...api().getPositionerProps() style=positionerStyle data-slot="dropdown-menu-positioner">
      <div
        ...api().getContentProps()
        data-slot="dropdown-menu-content"
        class=cn(
          "data-open:animate-in data-closed:animate-out data-closed:fade-out-0 data-open:fade-in-0 data-closed:zoom-out-95 data-open:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 ring-foreground/10 bg-popover text-popover-foreground min-w-32 rounded-none shadow-md ring-1 duration-100 mu-menu-target mu-menu-translucent z-50 max-h-(--radix-dropdown-menu-content-available-height) w-(--radix-dropdown-menu-trigger-width) origin-(--radix-dropdown-menu-content-transform-origin) overflow-x-hidden overflow-y-auto data-closed:overflow-hidden",
          className,
        )
      >
        <for|entry, index| of=entries>
          <if=entry.type === "separator">
            <div ...api().getSeparatorProps() data-slot="dropdown-menu-separator" class="bg-border -mx-1 h-px"/>
          </if>
          <else if=entry.type === "label">
            <div data-slot="dropdown-menu-label" data-inset=entry.inset || undefined class="text-muted-foreground px-2 py-2 text-xs data-inset:pl-7">
              <if=entry.content>
                <${entry.content}/>
              </if>
              <else>
                ${entry.label}
              </else>
            </div>
          </else>
          <else if=entry.type === "checkbox">
            <div
              ...api().getOptionItemProps({ type: "checkbox", value: entry.value ?? `item-${index}`, checked: entry.checked ?? false, disabled: entry.disabled })
              data-slot="dropdown-menu-checkbox-item"
              data-inset=entry.inset || undefined
              class="focus:bg-accent focus:text-accent-foreground focus:**:text-accent-foreground gap-2 rounded-none py-2 pr-8 pl-2 text-xs data-inset:pl-7 [&_svg:not([class*='size-'])]:size-4 relative flex cursor-default items-center outline-hidden select-none data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0"
            >
              <span ...api().getItemIndicatorProps({ value: entry.value ?? `item-${index}`, checked: entry.checked ?? false }) data-slot="dropdown-menu-checkbox-item-indicator" class="absolute right-2 flex items-center justify-center pointer-events-none">
                <if=entry.checked>
                  <Icon name="Check"/>
                </if>
              </span>
              <if=entry.content>
                <${entry.content}/>
              </if>
              <else>
                ${entry.label}
              </else>
              <if=entry.shortcut>
                <span data-slot="dropdown-menu-shortcut" class="text-muted-foreground group-focus/dropdown-menu-item:text-accent-foreground ml-auto text-xs tracking-widest">${entry.shortcut}</span>
              </if>
            </div>
          </else>
          <else if=entry.type === "radio">
            <div
              ...api().getOptionItemProps({ type: "radio", value: entry.value ?? `item-${index}`, checked: entry.checked ?? false, disabled: entry.disabled })
              data-slot="dropdown-menu-radio-item"
              data-inset=entry.inset || undefined
              class="focus:bg-accent focus:text-accent-foreground focus:**:text-accent-foreground gap-2 rounded-none py-2 pr-8 pl-2 text-xs data-inset:pl-7 [&_svg:not([class*='size-'])]:size-4 relative flex cursor-default items-center outline-hidden select-none data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0"
            >
              <span ...api().getItemIndicatorProps({ value: entry.value ?? `item-${index}`, checked: entry.checked ?? false }) data-slot="dropdown-menu-radio-item-indicator" class="pointer-events-none">
                <if=entry.checked>
                  <Icon name="Check"/>
                </if>
              </span>
              <if=entry.content>
                <${entry.content}/>
              </if>
              <else>
                ${entry.label}
              </else>
              <if=entry.shortcut>
                <span data-slot="dropdown-menu-shortcut" class="">${entry.shortcut}</span>
              </if>
            </div>
          </else>
          <else if=entry.type === "sub">
            <Submenu
              entries=entry.subEntries ?? []
              label=entry.label
              disabled=entry.disabled
              inset=entry.inset
              parent=getOwnService
              onChildReady=(childService) => api().setChild(childService)
            >
              <@trigger|childApi|>
                <div
                  ...api().getTriggerItemProps(childApi)
                  data-slot="dropdown-menu-sub-trigger"
                  data-inset=entry.inset || undefined
                  class="focus:bg-accent focus:text-accent-foreground data-open:bg-accent data-open:text-accent-foreground not-data-[variant=destructive]:focus:**:text-accent-foreground gap-2 rounded-none px-2 py-2 text-xs data-inset:pl-7 [&_svg:not([class*='size-'])]:size-4 flex cursor-default items-center outline-hidden select-none [&_svg]:pointer-events-none [&_svg]:shrink-0"
                >
                  ${entry.label}
                  <Icon name="ChevronRight" class="mu-rtl-flip ml-auto"/>
                </div>
              </@trigger>
            </Submenu>
          </else>
          <else>
            <div
              ...api().getItemProps({ value: entry.value ?? `item-${index}`, disabled: entry.disabled })
              data-slot="dropdown-menu-item"
              data-inset=entry.inset || undefined
              data-variant=entry.variant ?? "default"
              class="focus:bg-accent focus:text-accent-foreground data-[variant=destructive]:text-destructive data-[variant=destructive]:focus:bg-destructive/10 dark:data-[variant=destructive]:focus:bg-destructive/20 data-[variant=destructive]:focus:text-destructive data-[variant=destructive]:*:[svg]:text-destructive not-data-[variant=destructive]:focus:**:text-accent-foreground gap-2 rounded-none px-2 py-2 text-xs data-inset:pl-7 [&_svg:not([class*='size-'])]:size-4 group/dropdown-menu-item relative flex cursor-default items-center outline-hidden select-none data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0"
            >
              <if=entry.content>
                <${entry.content}/>
              </if>
              <else>
                ${entry.label}
              </else>
              <if=entry.shortcut>
                <span data-slot="dropdown-menu-shortcut" class="">${entry.shortcut}</span>
              </if>
            </div>
          </else>
        </for>
      </div>
    </div>
  </if>
</portal>

<return=api>

// One nested submenu: a real second `@zag-js/menu` machine instance, linked
// to its parent menu's raw service via `setParent`/`setChild` — the wiring
// zag's own connect() exposes for exactly this (`menu.connect(...).setParent`
// / `.setChild`, both documented to accept the *raw* MarkoService, not the
// connected api — confirmed against `@zag-js/menu@1.43.0`'s connect source).
// Marko gives this its own component instance (and therefore its own
// `<lifecycle>`) per call site, which is exactly the child-machine lifetime
// zag wants — same shape as `<toast-item>`'s per-toast child service linked
// to the toaster's group service. Copied from menubar/submenu.marko (see
// that file's header for the full toast-precedent rationale) — this is the
// same mechanical pattern, just dropdown-menu's own item shape and class
// strings.
//
// The trigger row lives in the PARENT menu's item list (it needs the
// parent's `getTriggerItemProps(childApi)`, which only the parent's api
// exposes), so this component renders only the sub-trigger's own subtree:
// the trigger row itself (via `<@trigger>`, receiving this submenu's api so
// the caller can call `getTriggerItemProps`) plus the popped-out content.
// Rendered by `dropdown-menu.marko` for `type: "sub"` entries. Supports one
// level of nesting (a submenu's own items are flat — item/separator/label
// only); a `type: "sub"` entry inside a submenu's `subEntries` is not wired.
import * as menu from "@zag-js/menu";
import { positionerStyle } from "marko-zag";
import Icon from "../icon/icon.marko";
import type { DropdownMenuItem } from "./dropdown-menu.marko";

export interface Input {
  /** This submenu's own item list — same entry shape as the top-level menu. */
  entries: DropdownMenuItem[];
  /** Label rendered on the sub-trigger row. */
  label?: string;
  disabled?: boolean;
  inset?: boolean;
  /** Getter for the parent menu's raw service — this submenu registers onto it via `setParent`. */
  parent: () => menu.Service | null;
  /**
   * Fires once this submenu's own raw service exists (on mount), so the
   * parent can complete the link with `parentApi().setChild(childService)` —
   * `setChild` needs the RAW service (see menu.connect's `child.prop("id")`),
   * which only exists after this component's own `<service>` has mounted.
   */
  onChildReady?: (childService: menu.Service) => void;
  /**
   * Trigger render-prop: receives this submenu's connected api so the caller
   * (the parent menu's item loop) can build the row with
   * `parentApi().getTriggerItemProps(childApi)`.
   */
  trigger: Marko.AttrTag<{ content: Marko.Body<[menu.Api]> }>;
}

<machine-props/machineProps from=input pick=menu.props/>
<service/service machine=() => menu.machine props=machineProps/>
<connect/api=(service, normalizeProps) =>
  menu.connect(service, normalizeProps)
  service=service
/>

// Link this submenu to its parent as soon as both raw services exist.
// `setParent`/`setChild` both take the raw MarkoService (see menu.connect's
// `parent.prop("id")` / `child.prop("id")` calls) — `<service>`'s onMount has
// already run for every ancestor by the time any descendant mounts (Marko
// mounts render bottom-up after the full tree commits), so `input.parent()`
// and `service.service` are both live here.
<lifecycle
  onMount() {
    const parentService = input.parent();
    const ownService = service.service;
    if (!parentService || !ownService) return;
    api().setParent(parentService);
    input.onChildReady?.(ownService);
  }
/>

<${input.trigger.content}(api())/>
<portal>
  <if=api().open>
    <div ...api().getPositionerProps() style=positionerStyle data-slot="dropdown-menu-sub-content-positioner">
      <div
        ...api().getContentProps()
        data-slot="dropdown-menu-sub-content"
        class="data-open:animate-in data-closed:animate-out data-closed:fade-out-0 data-open:fade-in-0 data-closed:zoom-out-95 data-open:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 ring-foreground/10 bg-popover text-popover-foreground min-w-[96px] rounded-none shadow-lg ring-1 duration-100 mu-menu-target mu-menu-translucent z-50 origin-(--radix-dropdown-menu-content-transform-origin) overflow-hidden"
      >
        <for|entry, index| of=input.entries>
          <const/value=entry.value ?? `sub-item-${index}`/>
          <if=entry.type === "separator">
            <div ...api().getSeparatorProps() data-slot="dropdown-menu-separator" class="bg-border -mx-1 h-px"/>
          </if>
          <else if=entry.type === "label">
            <div data-slot="dropdown-menu-label" data-inset=entry.inset || undefined class="text-muted-foreground px-2 py-2 text-xs data-inset:pl-7">
              ${entry.label}
            </div>
          </else>
          <else>
            <div
              ...api().getItemProps({ value, disabled: entry.disabled })
              data-slot="dropdown-menu-item"
              data-inset=entry.inset || undefined
              data-variant=entry.variant ?? "default"
              class="focus:bg-accent focus:text-accent-foreground data-[variant=destructive]:text-destructive data-[variant=destructive]:focus:bg-destructive/10 dark:data-[variant=destructive]:focus:bg-destructive/20 data-[variant=destructive]:focus:text-destructive data-[variant=destructive]:*:[svg]:text-destructive not-data-[variant=destructive]:focus:**:text-accent-foreground gap-2 rounded-none px-2 py-2 text-xs data-inset:pl-7 [&_svg:not([class*='size-'])]:size-4 group/dropdown-menu-item relative flex cursor-default items-center outline-hidden select-none data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0"
            >
              ${entry.label}
              <if=entry.shortcut>
                <span data-slot="dropdown-menu-shortcut" class="text-muted-foreground group-focus/dropdown-menu-item:text-accent-foreground ml-auto text-xs tracking-widest">${entry.shortcut}</span>
              </if>
            </div>
          </else>
        </for>
      </div>
    </div>
  </if>
</portal>
